70:   AppThemeData copyWith({
71:     final Brightness? brightness,
72:     final ThemeFonts? themeFonts,
73:     final ThemeColors? themeColors,
74:   }) {
75:     return AppThemeData.raw(
76:       brightness: brightness ?? this.brightness,
77:       themeFonts: themeFonts ?? this.themeFonts,
78:       themeColors: themeColors ?? this.themeColors,
79:     );
80:   }
81: 
82:   @override
83:   AppThemeData lerp(ThemeExtension<AppThemeData>? other, double t) {
84:     if (other is! AppThemeData) {
85:       return this;
86:     }
87: 
88:     return copyWith(
89:       themeFonts: themeFonts.lerp(other.themeFonts, t),
